#!/usr/bin/env bash
# Removes everything up.sh and the tests created, in reverse order, then checks that nothing is left.
#   down.sh          asks for confirmation
#   down.sh --yes    does not ask
# Do not edit this file while it runs: bash reads a script as it goes.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
export AWS_PAGER="" KUBECONFIG="$ROOT/.kube/config"
if [ "${1:-}" != "--yes" ]; then
  read -r -p "This destroys the cluster, its GPU nodes, the network and the state bucket. Type 'destroy' to continue: " answer
  [ "$answer" = "destroy" ] || { echo "aborted"; exit 1; }
fi
# Workloads first, so their pods are gone before the nodes are.
if [ -x "$ROOT/.tools/kubectl" ]; then
  "$ROOT/.tools/kubectl" --request-timeout=30s delete namespace rl-research --wait=true --timeout=300s 2>/dev/null || true
fi
(cd "$ROOT/terraform/20-platform" && terraform destroy -input=false -auto-approve) || (cd "$ROOT/terraform/20-platform" && terraform destroy -input=false -auto-approve)
(cd "$ROOT/terraform/10-cluster" && terraform destroy -input=false -auto-approve) || (cd "$ROOT/terraform/10-cluster" && terraform destroy -input=false -auto-approve)
# EKS creates each cluster's log group itself, so Terraform does not own it and it outlives the cluster.
aws logs delete-log-group --region us-east-1 --log-group-name /aws/eks/ds11-multi-task/cluster >/dev/null 2>&1 || true
"$ROOT/scripts/verify-clean.sh"
